def _hire_target(v, tasks_weight):
    units = int(math.ceil(tasks_weight / 19.0))
    if v.money < 400:
        cap = 4
    elif v.money < 1200:
        cap = 7
    elif v.money < 4000:
        cap = 10
    elif v.money < 9000:
        cap = 12
    elif v.money < 20000:
        cap = 13
    else:
        cap = 14
    return max(1, min(units, cap))


def _market(v, n_units, plant_budget):
    orders = []
    budget = v.money
    last = v.day >= LAST_DAY
    early = v.hour <= 3
    cap_hire = 4 if early else 0
    cap_seed = 2 if v.hour <= 6 else 1
    cap_sell = 3 if early else 7

    # 1. wheat for the animals — an unfed animal is gone for good
    feed_need = v.n_animals * (1 if v.day >= LAST_DAY - 1 else 2) + 3
    if v.n_animals and not last:
        have = v.shed.get("WHEAT", 0) + v.carried.get("WHEAT", 0)
        short = feed_need - have
        if short > 0:
            price = max(1, market_price("WHEAT", v.minv.get("WHEAT", 10000) - 1))
            room = max(0, 96 - v.shed_total)
            n = min(short, room, int(budget // price))
            if n > 0:
                orders.append(["BUY_PRODUCT", "WHEAT", n])
                budget -= n * price

    # 2. labour is cheap: fib(n) resets daily, and a hand is 23 extra actions
    if cap_hire and not last:
        weight = (2.0 * len(v.plants) + 4.5 * v.n_animals + 1.5 * len(v.weeds)
                  + 2.5 * min(len(v.empties), 6 + int(budget // 25)))
        target = _hire_target(v, weight)
        need = target - 1 - v.hires_today
        for _ in range(min(max(0, need), cap_hire)):
            if budget < 30:
                break
            orders.append(["HIRE"])
            budget -= 5

    # 3. sell everything above its reserve price, dearest first
    sells = []
    for item in PRODUCTS:
        have = v.shed.get(item, 0)
        if have <= 0:
            continue
        if item == "WHEAT" and not last:
            have -= feed_need
            if have <= 0:
                continue
        reserve = _reserve_price(v, item)
        n = _sell_quantity(v, item, have, reserve)
        if n > 0:
            sells.append((v.spot(item) * n, item, n))
    sells.sort(reverse=True)
    for _val, item, n in sells[:cap_sell]:
        orders.append(["SELL", item, n])

    # 4. seeds for the tiles we are about to plant
    if not last and v.day <= 25:
        fert_rich = (v.shed.get("FERTILIZER", 0) >= 8 or v.eff_price("FERTILIZER") < 45)
        ranking = _crop_ranking(v, fert_rich)
        free = len(v.empties)
        bought = 0
        for _score, crop, room in ranking:
            if bought >= cap_seed or free <= 0:
                break
            want = min(room, free, 12) - v.seeds.get(crop, 0)
            cost = CROPS[crop]["seed"]
            n = min(want, int(max(0.0, budget - 150) // cost))
            if n > 0:
                orders.append(["BUY_SEED", crop, n])
                budget -= n * cost
                free -= n
                bought += 1

    # 5. land.  25 tiles pay for themselves inside a week; buy as soon as the
    #    purchase still leaves enough to stock them with seed.
    nq = len(v.farm.get("unlocked_quadrants") or ["NW"]) - 1
    if 0 <= nq < 3 and v.day <= 23:
        price = [1000, 2000, 4000][nq]
        if budget >= price + 1400 and v.days_left >= 5:
            orders.append(["BUY_LAND"])
            budget -= price

    # 6. animals last: they are the best tile-day in the game but the slowest
    #    to pay back, so they only get money the rest of the plan did not need.
    if not last:
        want = _animal_wanted(v)
        for kind in ("SHEEP", "COW", "GOOSE"):
            n_want = want.get(kind, 0)
            if n_want <= 0:
                continue
            cost = ANIMALS[kind]["cost"]
            keep = 700 + 25 * len(v.empties)
            n = min(n_want, 3, int(max(0.0, budget - keep) // cost),
                    max(0, 96 - v.shed_total))
            if n > 0:
                orders.append(["BUY_ANIMAL", kind, n])
                budget -= n * cost
                break

    return orders[:10]
